    48	export function partitionTestFiles(files, count = 2, sizeOf = (file) => fs.statSync(path.resolve(cli, file)).size, durations = loadTestDurations()) {
    49	  if (!Number.isInteger(count) || count < 1 || count > 2) throw new RangeError("CLI test shard count must be 1 or 2");
