    47	    );
    48	    const suite = job.indexOf("run: npm --prefix cli test");
    49	    assert.ok(suite >= 0, `${jobName} runs the CLI suite`);
    50	    assert.match(job, /timeout-minutes: 45\n\s+run: npm --prefix cli test/, `${jobName} bounds the CLI suite to 45 minutes so a hung test process fails the job`);
    51	    const positions = REQUIRED_EVALUATOR_SETUP.map((step) => {
