import fs from "node:fs"; import path from "node:path";
import { listCliTestFiles, selectShardFiles, loadTestDurations, durationKey, partitionTestFiles } from "./scripts/test_shards.mjs";
const files = listCliTestFiles(); const d = loadTestDurations();
const w = (f) => d[durationKey(f)] > 0 ? d[durationKey(f)]*1000 : Math.max(1, fs.statSync(path.resolve(f)).size);
const totalW = files.reduce((t,f)=>t+w(f),0);
console.log("files", files.length, "measured", files.filter(f=>d[durationKey(f)]>0).length, "total weight", totalW);
const PROC_MIN = 66; // 2 concurrent processes x ~33 min (ci.yml comment): upper bound of serial process time
for (const N of [4, 8]) {
  const shards = Array.from({length:N},(_,i)=>selectShardFiles(files,{index:i+1,total:N}));
  const flat = shards.flat(); const set = new Set(flat);
  const disjoint = flat.length === set.size; const union = set.size === files.length && files.every(f=>set.has(f));
  console.log(`N=${N} union=${union} disjoint=${disjoint}`);
  shards.forEach((s,i)=>{ const sw=s.reduce((t,f)=>t+w(f),0); const inner=partitionTestFiles(s,2).map(p=>p.reduce((t,f)=>t+w(f),0));
    console.log(`  shard ${i+1}: files=${s.length} weight=${sw} share=${(100*sw/totalW).toFixed(1)}% est_process_min=${(PROC_MIN*sw/totalW).toFixed(1)} est_wall_min(2 procs)=${(PROC_MIN*Math.max(...inner)/totalW).toFixed(1)}`); });
}'

